Lemma sc_fin : forall (LF : list fframe) (lo shi spa ff fp px out k : Z)
    (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (loc gap : list cell) (j16 j32 : list byte) (h3 bg inn en mxw : word) (ioc bs D N : Z) (mx : mem)
    (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
  rw_cells bsegs mx spa loc -> Z.of_nat (cells_size loc) = 64 ->
  rw_cells bsegs mx (spa + 64) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -96 - (spa + 64) ->
  (spa = bv_unsigned sp + -160 \/ spa = bv_unsigned sp + -176) ->
  rw_cells bsegs mx (bv_unsigned sp + -96) (hz_saved s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs mx ff (sc_frm ff ioc fp h3 j16 j32) -> rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) sc_sh0 -> rw_cells bsegs mx fp [C1 (b8 1)] ->
  stk bsegs mx lo spa -> mem_inv bsegs mx ->
  as_RFS H ((1, ff, fp) :: LF) mx -> fresh_frame H LF 1 ff fp -> ACONST mx -> stack0 mx lo shi ->
  rw_cells bsegs mx (px + 112) [C8 bg; C8 inn; C8 (Z_to_bv 64 out); C8 (Z_to_bv 64 (out + k)); C8 en; C8 mxw] -> accessible mx (px + 128) 16 ->
  AIMG_TOP <= px -> px + 256 <= aceil -> px mod 8 = 0 -> (px + 256 + 16 <= as_FSB H \/ as_FSB H + AFS_SIZE <= px - 16) -> aapp px 256 ->
  0 <= out -> 0 <= k -> out + k < 2^64 ->
  (0 < k -> 0 < out) ->                                                        (* [comment removed for export] *)
  lo + 4096 + 176 <= bv_unsigned sp -> aceil <= lo ->
  evt bsegs (sc_fin_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF px out k lo shi ff fp bg inn en mxw mx)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 ff) (Z_to_bv 64 bs) (Z_to_bv 64 N) (Z_to_bv 64 D) (Z_to_bv 64 px) (Z_to_bv 64 k)
             (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SC_RET_CPY) fc None mx (seg_rom bsegs)).
