Definition sc_tail_W (lo spa px ff fp outp N : Z) : list (Z * Z) := ([(outp, outp + N); (lo, spa + 64)] ++ sc_fin_W px ff fp)%Z.

Definition sc_tail_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (px outp N D lo shi spa ff fp : Z) (bg inn en mxw : word) (ds : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch (sc_tail_W lo spa px ff fp outp N) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' (px + 112) [C8 bg; C8 inn; C8 (Z_to_bv 64 (outp + N)); C8 (Z_to_bv 64 (outp + N)); C8 en; C8 mxw]
    /\ (1 <= N -> rw_cells bsegs m' outp [CB (Z.to_nat N) ds]) /\ bytes_at bsegs m' D ds
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.
