Lemma sc_tail : forall (LF : list fframe) (lo shi spa ff fp px outp : Z)
    (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (gap : list cell) (p0 p8 p16 p32 p40 p48 p56 j16 j32 ds junk : list byte) (h3 bg inn en mxw : word) (ioc bs D N : Z) (mx : mem)
    (rax t0 t1 t2 a2 a3 a4 a5 a6 a7 xs7 t3 t4 t5 t6 : word),
  rw_cells bsegs mx spa (sc_loc p0 p8 p16 ff p32 p40 p48 p56) ->
  rw_cells bsegs mx (spa + 64) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -96 - (spa + 64) ->
  (spa = bv_unsigned sp + -160 \/ spa = bv_unsigned sp + -176) ->
  rw_cells bsegs mx (bv_unsigned sp + -96) (hz_saved s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs mx ff (sc_frm ff ioc fp h3 j16 j32) -> rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) sc_sh0 -> rw_cells bsegs mx fp [C1 (b8 1)] ->
  stk bsegs mx lo spa -> mem_inv bsegs mx ->
  as_RFS H ((1, ff, fp) :: LF) mx -> fresh_frame H LF 1 ff fp -> ACONST mx -> stack0 mx lo shi ->
  rw_cells bsegs mx (px + 112) [C8 bg; C8 inn; C8 (Z_to_bv 64 outp); C8 (Z_to_bv 64 (outp + N)); C8 en; C8 mxw] -> accessible mx (px + 128) 16 ->
  AIMG_TOP <= px -> px + 256 <= aceil -> px mod 8 = 0 -> (px + 256 + 16 <= as_FSB H \/ as_FSB H + AFS_SIZE <= px - 16) -> aapp px 256 ->
  0 <= N < 2^26 -> 0 <= outp -> outp + N < 2^64 -> 0 <= D -> D + N < 2^64 -> length ds = Z.to_nat N ->
  (1 <= N -> rw_cells bsegs mx outp [CB (Z.to_nat N) junk] /\ accessible mx outp N /\ shvis mx outp (outp + N) /\ in_app_mem outp (outp + N)
             /\ aapp outp N /\ (outp + N + 16 <= as_FSB H \/ as_FSB H + AFS_SIZE <= outp - 16)
             /\ (D + N <= outp \/ outp + N <= D) /\ (outp + N <= px + 112 \/ px + 160 <= outp)) ->
  (1 <= N -> bytes_at bsegs mx D ds /\ accessible mx D N /\ shvis mx D (D + N) /\ in_app_mem D (D + N) /\ D + N <= aceil /\ (D + N <= px + 128 \/ px + 136 <= D)
             /\ (D + N + 16 <= as_FSB H \/ as_FSB H + AFS_SIZE <= D - 16)) ->
  lo + 4096 + 176 <= bv_unsigned sp -> aceil <= lo ->
  evt bsegs (sc_tail_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF px outp N D lo shi spa ff fp bg inn en mxw ds mx)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) (Z_to_bv 64 outp) (Z_to_bv 64 N) a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 ff) (Z_to_bv 64 bs) (Z_to_bv 64 N) (Z_to_bv 64 D) (Z_to_bv 64 px) xs7
             (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3 t4 t5 t6)
